using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;using UnityEngine.AI;using System.IO;using System.Linq;using System.Collections.Generic;
[InitializeOnLoad]public static class TerracedRoadRelief {
 static TerracedRoadRelief(){EditorApplication.delayCall+=Run;}
 static float Smooth(float a,float b,float x)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
 static void Run(){const string e="Evidence/terraced-village-20261030/";if(EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(e+"window-effects.txt")||File.Exists(e+"road-relief-final.txt"))return;var scene=EditorSceneManager.GetActiveScene();if(!scene.name.Contains("TerracedInteriors"))return;var terrain=Object.FindObjectOfType<Terrain>();var data=terrain.terrainData;var old=Object.Instantiate(data);var buildings=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Where(t=>System.Text.RegularExpressions.Regex.IsMatch(t.name,@"^B\d\d ")&&t.Find("door")).ToArray();var bounds=buildings.Select(t=>{var rs=t.GetComponentsInChildren<Renderer>().Where(r=>!r.name.Contains("window")&&!r.name.Contains("glass")).ToArray();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}).ToArray();int n=data.heightmapResolution;var h=data.GetHeights(0,0,n,n);for(int y=0;y<n;y++)for(int x=0;x<n;x++){float wx=terrain.transform.position.x+x/(float)(n-1)*data.size.x,wz=terrain.transform.position.z+y/(float)(n-1)*data.size.z;float bump=1.05f*(.5f+.5f*Mathf.Sin((wx+34)*.30f))*Mathf.Exp(-(wz+5.5f)*(wz+5.5f)/50)*Smooth(-45,-35,wx)*(1-Smooth(36,48,wx));foreach(var b in bounds){float dx=Mathf.Max(0,Mathf.Abs(wx-b.center.x)-b.extents.x-.3f),dz=Mathf.Max(0,Mathf.Abs(wz-b.center.z)-b.extents.z-.3f);bump*=Smooth(0,3.2f,Mathf.Sqrt(dx*dx+dz*dz));}h[y,x]+=bump/data.size.y;}data.SetHeights(0,0,h);EditorUtility.SetDirty(data);
 var player=Object.FindObjectOfType<HunterTorchPose>();var moved=new HashSet<Transform>(buildings);System.Action<Transform> shift=t=>{if(!t||moved.Any(a=>t==a||t.IsChildOf(a)))return;var p=t.position;float before=old.GetInterpolatedHeight((p.x-terrain.transform.position.x)/old.size.x,(p.z-terrain.transform.position.z)/old.size.z);t.position+=Vector3.up*(terrain.SampleHeight(p)-before);moved.Add(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t);};var forest=GameObject.Find("Forest");if(forest)foreach(Transform t in forest.transform)shift(t);foreach(var a in Resources.FindObjectsOfTypeAll<NavMeshAgent>().Where(a=>a.gameObject.scene==scene))shift(a.transform);foreach(var c in Resources.FindObjectsOfTypeAll<DemoInteractable>().Where(c=>c.gameObject.scene==scene))shift(c.transform);shift(player.GetComponent<DemoPrologueFlow>().checkpoint);foreach(var r in Object.FindObjectsOfType<Renderer>()){if(r is SkinnedMeshRenderer||r.transform.IsChildOf(player.transform)||r.GetComponentInParent<DemoEnemy>()||r.GetComponentInParent<Terrain>())continue;if(r.name.ToLowerInvariant().Contains("ground")&&r.bounds.size.x>70)continue;shift(r.transform);}Object.DestroyImmediate(old);
 var surface=Object.FindObjectOfType<NavMeshSurface>();surface.RemoveData();surface.navMeshData=null;surface.BuildNavMesh();AssetDatabase.CreateAsset(surface.navMeshData,AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Environment/TerracedVillage/TerracedReliefNavMesh.asset"));EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();string text="Added smoothly rolling road crests up to 1.05m, ~21m cycle, feathered around level building foundations; terrain props regrounded; separate NavMesh rebaked.\n";for(float x=-42;x<37;x+=4)text+="road x="+x+" z=-5.5 height="+terrain.SampleHeight(new Vector3(x,0,-5.5f)).ToString("F2")+"\n";File.WriteAllText(e+"road-relief-final.txt",text);}
}
